// STATE.md and LOG.md regenerated from the thread (m6.7): for collaborators who do not use ariadne, or
// to leave it. Same sections as the `handoff` format, so `readState` reads them back. Pure.

import { isWork, makeGraph } from './graph.mjs'
import { words } from './i18n.mjs'

/** The first line of a generated file: init and migrate leave such files alone. */
export const GENERATED = '<!-- generated by ariadne from .ariadne/: change the thread, not this file -->'
export const isGenerated = text => text.startsWith(GENERATED)

const say = words({
  en: { active: 'in progress', decision: 'Decision', risk: 'Risk', thread: '- The thread: `.ariadne/` (`ariadne card`, `ariadne open`)' },
  it: { active: 'in corso', decision: 'Decisione', risk: 'Rischio', thread: '- Il filo: `.ariadne/` (`ariadne card`, `ariadne open`)' },
})

const NEXT_MAX = 6
const said = n => (n.what && n.what !== n.title ? `${n.title}: ${n.what}` : n.title)

export function exportState(nodes, thread, { project, at }) {
  const g = makeGraph(nodes)
  const milestoneOf = id => [id, ...g.containers(id)].map(g.get).find(n => n?.kind === 'milestone')
  const current = g.get(thread.current)
  const milestone = (current && milestoneOf(current.id)) ?? nodes.find(n => n.kind === 'milestone' && n.status === 'active')
  const inside = n => milestone && milestoneOf(n.id)?.id === milestone.id
  const next = [
    ...(current && current.kind !== 'milestone' ? [`${current.id} ${said(current)} (${say('active')})`] : []),
    ...nodes.filter(n => n.status === 'todo' && isWork(n) && n.kind !== 'milestone' && inside(n)).map(n => `${n.id} ${said(n)}`),
  ].slice(0, NEXT_MAX)
  const open = [
    ...nodes.filter(n => n.kind === 'decision' && n.status === 'todo').map(n => `- ${say('decision')} ${n.id} ${said(n)}`),
    ...nodes.filter(n => n.kind === 'risk' && n.status === 'todo' && inside(n)).map(n => `- ${say('risk')} ${n.id} ${said(n)}`),
  ]
  return [
    GENERATED,
    `# State — ${project}`,
    `Updated: ${at.slice(0, 10)} · ariadne export`,
    '', '## Milestone', milestone ? said(milestone) : '-',
    '', '## Next', ...next.map((line, i) => `${i + 1}. ${line}`),
    '', '## Open decisions and risks', ...(open.length ? open : ['-']),
    '', '## Pointers', say('thread'),
    '',
  ].join('\n')
}

/** One line per closed node, from the diary: `- <date> · <what> · <commit>`. */
export function exportLog(log) {
  const lines = log.filter(e => e.op === 'close').map(e => {
    const commit = (e.proof ?? []).find(p => p.type === 'commit')?.ref
    return `- ${e.at.slice(0, 10)} · ${e.text}${commit ? ` · ${commit}` : ''}`
  })
  return [GENERATED, '# Log', '', ...lines, ''].join('\n')
}
